    @Test
    public void testForOffsetHoursMinutes_NegativeOffset() {
        // Test -5:30 (hoursOffset = -5, minutesOffset = 30)
        // Logic: hoursInMinutes = -300. hoursInMinutes < 0 is true.
        // minutesOffset = safeAdd(-300, -30) = -330.
        // offset = -330 * 60 * 1000
        DateTimeZone zone = DateTimeZone.forOffsetHoursMinutes(-5, 30);
        assertEquals(-330 * 60 * 1000, zone.getOffset(0));
    }










