        // Attempt to trigger ArithmeticException in FieldUtils.safeMultiply or safeAdd
        // Integer.MAX_VALUE is ~2 billion. 
        // hoursOffset = Integer.MAX_VALUE will definitely overflow when multiplied by 60.
        try {
            DateTimeZone.forOffsetHoursMinutes(Integer.MAX_VALUE, 0);
            fail("Should have thrown IllegalArgumentException due to overflow");
        } catch (IllegalArgumentException e) {
            assertEquals("Offset is too large", e.getMessage());
        }
    }




